import { Router } from "express";
import { Permission } from "../../constants/roles.constant.js";
import { authMiddleware } from "../../core/middlewares/auth.middleware.js";
import { permissionMiddleware } from "../../core/middlewares/rbac.middleware.js";
import { asyncHandler } from "../../core/utils/async-handler.js";
import { validate } from "../../core/utils/validate.js";
import { categoryController } from "./category.controller.js";
import { createCategorySchema, updateCategorySchema } from "./category.dto.js";
const router = Router();
router.use(authMiddleware);
router.get("/", permissionMiddleware(Permission.CATEGORIES_READ), asyncHandler(categoryController.findAll));
router.get("/:id", permissionMiddleware(Permission.CATEGORIES_READ), asyncHandler(categoryController.findById));
router.post("/", permissionMiddleware(Permission.CATEGORIES_CREATE), validate(createCategorySchema), asyncHandler(categoryController.create));
router.patch("/:id", permissionMiddleware(Permission.CATEGORIES_UPDATE), validate(updateCategorySchema), asyncHandler(categoryController.update));
router.delete("/:id", permissionMiddleware(Permission.CATEGORIES_DELETE), asyncHandler(categoryController.remove));
export default router;
